 sealed class Risk{
  public float[] weights,prior;public int updates;public float brier;public float change;
  public Risk(Prior p){prior=(float[])p.weights.Clone();Reset();}
  public void Reset(){weights=(float[])prior.Clone();updates=0;brier=0;change=0;}
  public static float[] Features(Vector3 p,Vector3 v){float d=p.magnitude,vv=v.sqrMagnitude,t=Mathf.Clamp(-Vector3.Dot(p,v)/(vv+1e-6f),0,1.2f),closest=(p+v*t).magnitude,closing=-Vector3.Dot(p,v)/(d*Mathf.Sqrt(vv)+1e-6f);return new[]{1f,d/30,closest/12,t/1.2f,closing,Mathf.Sqrt(vv)/25};}
  public float Predict(float[] x){float s=0;for(int i=0;i<weights.Length;i++)s+=weights[i]*x[i];return 1/(1+Mathf.Exp(-Mathf.Clamp(s,-25,25)));}
  public float Predict(Vector3 p,Vector3 v){float d=p.magnitude,vv=v.sqrMagnitude,t=Mathf.Clamp(-Vector3.Dot(p,v)/(vv+1e-6f),0,1.2f);float z=weights[0]+weights[1]*d/30+weights[2]*(p+v*t).magnitude/12+weights[3]*t/1.2f-weights[4]*Vector3.Dot(p,v)/(d*Mathf.Sqrt(vv)+1e-6f)+weights[5]*Mathf.Sqrt(vv)/25;return 1/(1+Mathf.Exp(-Mathf.Clamp(z,-25,25)));}
  public void Observe(float[] x,bool danger){float y=danger?1:0,p=Predict(x),e=p-y;for(int i=0;i<weights.Length;i++)weights[i]-=.02f*e*x[i];if(updates<int.MaxValue)updates++;brier=updates==1?e*e:Mathf.Lerp(brier,e*e,.05f);float sum=0;for(int i=0;i<weights.Length;i++)sum+=Mathf.Pow(weights[i]-prior[i],2);change=Mathf.Sqrt(sum);}
 }
