 Material M(Color c,bool additive=false){var m=new Material(additive?glow:lit);m.SetColor(additive?"_Color":"_BaseColor",c);if(!additive)m.SetFloat("_Smoothness",.55f);return m;}
 Transform Shape(string name,PrimitiveType type,Vector3 p,Vector3 scale,Color c,Transform parent=null){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=M(c);Destroy(g.GetComponent<Collider>());return g.transform;}
 LineRenderer Line(string name,Color c,float w){var l=new GameObject(name).AddComponent<LineRenderer>();l.material=M(c,true);l.widthMultiplier=w;l.numCapVertices=2;return l;}
 void Ring(Transform parent,float radius,Color c,int n=100){var l=Line("Accretion LOD • simplified distant visual",c,.045f);l.transform.SetParent(parent,false);l.useWorldSpace=false;l.loop=true;l.positionCount=n;var points=new Vector3[n];for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n;points[i]=new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius);}l.SetPositions(points);}
 static int SectorSeed(long x,long y,long z){return unchecked((int)(x*73856093L ^ y*19349663L ^ z*83492791L ^ 78193));}
 Vector3 SectorCenter(long x,long y,long z){return new Vector3((float)(x-cellX)*80,(float)(y-cellY)*80,(float)(z-cellZ)*80);}
 Vector3 HolePosition(long x,long y,long z){var r=new System.Random(SectorSeed(x,y,z));Vector3 jitter=new Vector3((float)r.NextDouble()*30-15,(float)r.NextDouble()*30-15,(float)r.NextDouble()*30-15);return SectorCenter(x,y,z)+((x==0&&y==0&&z==0)?Vector3.zero:jitter);}
 void DisposeSector(Sector a){var mesh=a.root.GetComponent<MeshFilter>();if(mesh!=null)Destroy(mesh.sharedMesh);var materials=new HashSet<Material>();foreach(var r in a.root.GetComponentsInChildren<Renderer>())materials.Add(r.sharedMaterial);foreach(var m in materials)Destroy(m);Destroy(a.root);}
 void Stream(bool force=false){
  if(!legacyUniverse){StreamExpanse(force);return;}
  Vector3 p=Pos(player);long cx=cellX+(long)Mathf.Floor(p.x/80),cy=cellY+(long)Mathf.Floor(p.y/80),cz=cellZ+(long)Mathf.Floor(p.z/80);
  var centers=new List<Vector3>{p};if(expedition!=null&&expedition.OnFoot)centers.Add(expedition.Focus);if(agents!=null)foreach(var actor in agents)if(actor.status==0)centers.Add(Pos(actor.state));foreach(var shot in shots)if(!shot.dead)centers.Add(Pos(shot.state));
  var remove=new List<string>();foreach(var kv in sectors){float nearest=99999;foreach(var center in centers)nearest=Mathf.Min(nearest,Vector3.Distance(kv.Value.hole.P,center));if(nearest>123)remove.Add(kv.Key);}foreach(var key in remove){DisposeSector(sectors[key]);sectors.Remove(key);}
  foreach(var region in centers){cx=cellX+(long)Mathf.Floor(region.x/80);cy=cellY+(long)Mathf.Floor(region.y/80);cz=cellZ+(long)Mathf.Floor(region.z/80);
  for(long x=cx-2;x<=cx+2;x++)for(long y=cy-2;y<=cy+2;y++)for(long z=cz-2;z<=cz+2;z++){
   string key=x+"/"+y+"/"+z;if(sectors.ContainsKey(key)||sectors.Count>=128)continue;Vector3 hp=HolePosition(x,y,z);if(Vector3.Distance(hp,region)>112)continue;
   int seed=SectorSeed(x,y,z);var root=GalaxyBackdrop.Chunk(SectorCenter(x,y,z),seed,seed&3);var holeRoot=new GameObject("Sector black-hole LOD");holeRoot.transform.SetParent(root.transform,false);holeRoot.transform.position=hp;
   Shape("Distant shadow approximation",PrimitiveType.Sphere,Vector3.zero,Vector3.one*3.6f,Color.black,holeRoot.transform);for(int j=0;j<12;j++)Ring(holeRoot.transform,2.2f+j*.3f,new Color(1,.35f+.02f*j,.08f,.4f));
   sectors.Add(key,new Sector{x=x,y=y,z=z,seed=seed,root=root,hole=new Hole{x=hp.x,y=hp.y,z=hp.z,mu=18+(seed&3),capture=1.8}});totalSectors++;
  }
  }
  var fields=new List<Hole>();holeModels.Clear();foreach(var a in sectors.Values){fields.Add(a.hole);holeModels.Add(a.root.transform.Find("Sector black-hole LOD").gameObject);}world.holes=fields.ToArray();bh_set_holes(world.holes,world.holes.Length);bh_set_gravity_window(60,100);SyncPlanets(centers);
 }

 void SyncPlanets(List<Vector3> centers){if(expedition==null)return;
  if(!expedition.planets.Exists(a=>a.key=="HOME"))expedition.Add("HOME","PELAGOS",new Vector3(-14-(float)cellX*80,-34-(float)cellY*80,42-(float)cellZ*80),22,4);
  expedition.RemoveFar(centers);
  foreach(var region in centers){long cx=cellX+(long)Mathf.Floor(region.x/80),cy=cellY+(long)Mathf.Floor(region.y/80),cz=cellZ+(long)Mathf.Floor(region.z/80);
   for(long x=cx-2;x<=cx+2;x++)for(long y=cy-2;y<=cy+2;y++)for(long z=cz-2;z<=cz+2;z++){
    if(x==0&&y==0&&z==0)continue;int seed=SectorSeed(x,y,z);if((seed&15)!=0)continue;Vector3 pos=HolePosition(x,y,z)+new Vector3(34,-30,32);if(Vector3.Distance(pos,region)>112)continue;string key=x+"/"+y+"/"+z;float radius=18+((seed>>4)&3)*1.5f;bool safe=true;
    for(long a=x-1;a<=x+1;a++)for(long b=y-1;b<=y+1;b++)for(long c=z-1;c<=z+1;c++)if(Vector3.Distance(pos,HolePosition(a,b,c))<radius+16)safe=false;
    foreach(var planet in expedition.planets)if(planet.key!=key&&Vector3.Distance(pos,planet.body.P)<radius+(float)planet.body.radius+20)safe=false;
    if(safe)expedition.Add(key,"VESPER "+(seed&4095).ToString("X"),pos,radius,seed);
   }
  }
 }
 public void AdvancePrediction(ref Vector3 p,ref Vector3 v,Vector3 u,float dt){if(expedition!=null&&expedition.InAtmosphere(p)){var state=Make(p,v);Step(ref state,u,dt);p=Pos(state);v=Vel(state);}else{v+=Predict(p,u)*dt;p+=v*dt;}}
 static void MoveState(ref OrbitDemo.State state,Vector3 shift){state.x-=shift.x;state.y-=shift.y;state.z-=shift.z;}
 void FloatingOrigin(){Vector3 p=expedition!=null&&expedition.OnFoot?expedition.Focus:Pos(player);if(p.magnitude<240)return;Vector3 shift=new Vector3(Mathf.Round(p.x/80)*80,Mathf.Round(p.y/80)*80,Mathf.Round(p.z/80)*80);RebaseOrigin(shift);}
 void RebaseOrigin(Vector3 shift){cellX+=(long)(shift.x/80);cellY+=(long)(shift.y/80);cellZ+=(long)(shift.z/80);originShifts++;cam.transform.position-=shift;if(inTidal){captureCenter-=shift;captureEntry-=shift;}
  MoveState(ref player,shift);rocket.position=Pos(player);foreach(var a in agents){MoveState(ref a.state,shift);a.root.position-=shift;for(int i=0;i<a.history.Count;i++)a.history[i]-=shift;a.trail.SetPositions(a.history.ToArray());}sim.state=agents[0].state;foreach(var shot in shots){MoveState(ref shot.state,shift);shot.previous-=shift;for(int i=0;i<shot.points.Count;i++)shot.points[i]-=shift;shot.root.transform.position-=shift;shot.trail.SetPositions(shot.points.ToArray());}foreach(var part in salvage){part.p-=shift;part.root.transform.position-=shift;}foreach(var a in sectors.Values){var h=a.hole;h.x-=shift.x;h.y-=shift.y;h.z-=shift.z;a.hole=h;a.root.transform.position-=shift;}CivilShift(shift);if(expedition!=null)expedition.Shift(shift);if(surface!=null)surface.Shift(shift);if(space!=null)space.Shift(shift);sim.ClearTrail();Stream(true);
 }
 void SpawnOpponent(int i,bool initial=false){var a=agents[i];Vector3 p;if(initial)p=legacyUniverse?new Vector3(-8+i*1.4f,9+(i%2)*2,4+(i-2)*2.3f):Pos(player)+new Vector3(25+i*1.4f,5+(i%2)*2,20+(i-2)*2.3f);else{
  Vector3 direction=shipRotation*Quaternion.Euler((float)dice.NextDouble()*50-25,(float)dice.NextDouble()*110-55,0)*Vector3.forward;p=Pos(player)+direction*(24+(float)dice.NextDouble()*14);if(NearHazard(p)<7)p+=Vector3.up*12;
 }
  a.state=Make(p,new Vector3(2.8f,.15f,(i-2)*.14f));a.status=0;a.planTime=i*.06f;a.action=Vector3.zero;a.history.Clear();a.root.gameObject.SetActive(true);a.trail.positionCount=0;a.attacker=i>=2;a.fireTime=4+(float)dice.NextDouble()*2;a.respawn=0;spawned++;
 }
 void BuildOpponents(){
  var original=GameObject.Find("Astronaut • placeholder").transform;CinematicPresentation.DetailAstronaut(original);agents=new Opponent[5];string[] names={"NOVA / CREW","ORION / CREW","MOSS / ALIEN","IRIS / ALIEN","SOL / ANDROID"};Color[] colors={new Color(.9f,.9f,.9f),new Color(.25f,.65f,1),new Color(.35f,1,.45f),new Color(.75f,.35f,1),new Color(1,.7f,.15f)};
  for(int i=0;i<agents.Length;i++){
   Transform root=i==0?original:Instantiate(original.gameObject).transform;root.name=names[i];if(i>0)foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=0;
   if(i>0)foreach(var r in root.GetComponentsInChildren<Renderer>())if(r.name=="Pressure suit"||r.name=="Helmet")r.sharedMaterial=M(colors[i]);
   if(i==2||i==3){Shape("Alien eye L",PrimitiveType.Sphere,new Vector3(-.12f,.62f,-.32f),new Vector3(.13f,.2f,.06f),Color.black,root);Shape("Alien eye R",PrimitiveType.Sphere,new Vector3(.12f,.62f,-.32f),new Vector3(.13f,.2f,.06f),Color.black,root);Shape("Antenna",PrimitiveType.Sphere,new Vector3(0,1.02f,0),new Vector3(.13f,.36f,.13f),colors[i],root);}
   if(i>=2){Shape("Alien interceptor rig",PrimitiveType.Cube,new Vector3(0,-.2f,.2f),new Vector3(1.15f,.15f,.65f),new Color(.2f,.27f,.36f),root);for(int sign=-1;sign<=1;sign+=2)Shape("Interceptor engine pod",PrimitiveType.Capsule,new Vector3(sign*.65f,-.17f,.2f),new Vector3(.22f,.42f,.22f),colors[i],root).localRotation=Quaternion.Euler(90,0,0);}
   agents[i]=new Opponent{name=names[i],root=root,trail=Line(names[i]+" actual trail",new Color(colors[i].r,colors[i].g,colors[i].b,.35f),.025f)};
  }
 }
