  int count=1+tiers[2]+(civilization==null?0:Mathf.Max(0,civilization.blueprint-1));
  float shotSpeed=civilization==null||civilization.blueprint<2?18:civilization.blueprint==2?95:130;
  float spread=2.8f/(1+.7f*tiers[3]);
  if(voyager!=null){count=voyager.weapon==1?1:voyager.weapon==2?5:count;shotSpeed=voyager.weapon==1?240:voyager.weapon==2?115:135;spread=voyager.weapon==2?7:1.5f;voyager.heat=Mathf.Min(110,voyager.heat+(voyager.weapon==1?28:voyager.weapon==2?24:12));}
